function(container, apiUrl, tables) {
  // ===== 1. 比較データ構造 =====
  const sampleVersions = {
    'doc-001': {
      name: '基本契約書',
      type: 'contract',
      versions: [
        {
          id: 'v1',
          number: 1,
          date: '2024-01-15',
          creator: '田中太郎',
          content: '第1条 契約の目的\n本契約は、甲と乙の間における基本的な取引関係を定めるものである。\n\n第2条 契約金額\n契約金額は1,000,000円とする。\n\n第3条 支払い条件\n支払いは月末締め翌月末払いとする。\n\n第4条 契約期間\n本契約は1年間とし、自動更新される。'
        },
        {
          id: 'v2',
          number: 2,
          date: '2024-02-10',
          creator: '鈴木花子',
          content: '第1条 契約の目的\n本契約は、甲と乙の間における基本的な取引関係を定めるものである。\n\n第2条 契約金額\n契約金額は1,200,000円とする。\n\n第3条 支払い条件\n支払いは月末締め翌月末払いとする。\n\n第4条 契約期間\n本契約は2年間とし、自動更新される。\n\n第5条 解約条件\n本契約は書面による通知により解約できる。'
        },
        {
          id: 'v3',
          number: 3,
          date: '2024-03-05',
          creator: '佐藤次郎',
          content: '第1条 契約の目的\n本契約は、甲と乙の間における基本的な取引関係を定めるものである。\n\n第2条 契約金額\n契約金額は1,200,000円とする。\n\n第3条 支払い条件\n支払いは月末締め翌月末払いとする。\n\n第4条 契約期間\n本契約は2年間とし、自動更新される。\n\n第5条 解約条件\n本契約は書面による通知により解約できる。\n\n第6条 秘密保持\n甲乙は相手方の秘密情報を厳格に保護する。'
        }
      ]
    },
    'doc-002': {
      name: 'サービス提案書',
      type: 'proposal',
      versions: [
        {
          id: 'v1',
          number: 1,
          date: '2024-01-20',
          creator: '山田太郎',
          content: '提案概要\n本提案は、貴社向けのカスタムシステム開発サービスです。\n\n提供内容\n- 要件定義\n- 基本設計\n- 詳細設計\n- 実装\n- テスト\n\n納期: 6ヶ月\n費用: 5,000,000円'
        },
        {
          id: 'v2',
          number: 2,
          date: '2024-02-15',
          creator: '山田太郎',
          content: '提案概要\n本提案は、貴社向けのカスタムシステム開発サービスです。\n\n提供内容\n- 要件定義\n- 基本設計\n- 詳細設計\n- 実装\n- テスト\n- 保守運用（1年間）\n\n納期: 6ヶ月\n費用: 6,000,000円\n\n特典: 初回導入支援無料'
        }
      ]
    }
  };

  // ===== 2. 差分計算関数 =====
  function calculateDiff(text1, text2) {
    const lines1 = text1.split('\n');
    const lines2 = text2.split('\n');
    const changes = [];

    const maxLen = Math.max(lines1.length, lines2.length);
    for (let i = 0; i < maxLen; i++) {
      const line1 = lines1[i] || '';
      const line2 = lines2[i] || '';

      if (line1 !== line2) {
        if (!line1) {
          changes.push({ type: 'added', line: line2, index: i });
        } else if (!line2) {
          changes.push({ type: 'deleted', line: line1, index: i });
        } else {
          changes.push({ type: 'modified', oldLine: line1, newLine: line2, index: i });
        }
      }
    }
    return changes;
  }

  // ===== 3. ハイライト付きコンテンツ描画 =====
  function renderHighlightedContent(text, changes, isVersion2 = false) {
    const lines = text.split('\n');
    const changedIndices = new Set();
    const changeMap = {};

    changes.forEach(change => {
      changedIndices.add(change.index);
      changeMap[change.index] = change;
    });

    return lines.map((line, idx) => {
      const change = changeMap[idx];
      let bgColor = 'transparent';
      let borderColor = 'transparent';

      if (change) {
        if (change.type === 'added') {
          bgColor = 'rgba(34,197,94,0.15)';
          borderColor = '#22c55e';
        } else if (change.type === 'deleted') {
          bgColor = 'rgba(239,68,68,0.15)';
          borderColor = '#ef4444';
        } else if (change.type === 'modified') {
          bgColor = 'rgba(255,193,7,0.15)';
          borderColor = '#ffc107';
        }
      }

      return `<div style="padding: 0.5rem; margin: 0.25rem 0; background: ${bgColor}; border-left: 3px solid ${borderColor}; border-radius: 0.25rem; white-space: pre-wrap; word-break: break-word;">${line || '&nbsp;'}</div>`;
    }).join('');
  }

  // ===== 4. 変更箇所一覧描画 =====
  function renderChangesList(changes) {
    if (changes.length === 0) {
      return '<p style="color: var(--text-muted); font-size: 0.875rem;">変更なし</p>';
    }

    return changes.map(change => {
      let typeLabel = '';
      let typeColor = '';
      let bgColor = '';
      let description = '';

      if (change.type === 'added') {
        typeLabel = '追加';
        typeColor = '#22c55e';
        bgColor = 'rgba(34,197,94,0.08)';
        description = change.line;
      } else if (change.type === 'deleted') {
        typeLabel = '削除';
        typeColor = '#ef4444';
        bgColor = 'rgba(239,68,68,0.08)';
        description = change.line;
      } else if (change.type === 'modified') {
        typeLabel = '変更';
        typeColor = '#ffc107';
        bgColor = 'rgba(255,193,7,0.08)';
        description = `${change.oldLine} → ${change.newLine}`;
      }

      return `
        <div style="padding: 0.5rem; border-left: 3px solid ${typeColor}; background: ${bgColor}; border-radius: 0.25rem;">
          <div style="font-size: 0.75rem; font-weight: 500; color: ${typeColor};">${typeLabel}</div>
          <div style="font-size: 0.875rem; color: var(--text); margin-top: 0.25rem; white-space: pre-wrap; word-break: break-word;">${description}</div>
        </div>
      `;
    }).join('');
  }

  // ===== 5. 比較実行 =====
  function executeComparison() {
    const docType = container.querySelector('[data-testid="document-select"]').value;
    const docId = container.querySelector('[data-testid="document-id-select"]').value;
    const version1Id = container.querySelector('[data-testid="version-1-select"]').value;
    const version2Id = container.querySelector('[data-testid="version-2-select"]').value;

    if (!docType || !docId || !version1Id || !version2Id) {
      alert('ドキュメント、バージョンを全て選択してください');
      return;
    }

    if (version1Id === version2Id) {
      alert('異なるバージョンを選択してください');
      return;
    }

    const doc = sampleVersions[docId];
    if (!doc) {
      alert('ドキュメントが見つかりません');
      return;
    }

    const v1 = doc.versions.find(v => v.id === version1Id);
    const v2 = doc.versions.find(v => v.id === version2Id);

    if (!v1 || !v2) {
      alert('バージョンが見つかりません');
      return;
    }

    // 差分計算
    const changes = calculateDiff(v1.content, v2.content);

    // バージョン情報表示
    container.querySelector('#version-1-info').textContent = `v${v1.number}.0 (${v1.date}) - 作成者: ${v1.creator}`;
    container.querySelector('#version-2-info').textContent = `v${v2.number}.0 (${v2.date}) - 作成者: ${v2.creator}`;

    // コンテンツ表示（ハイライト付き）
    container.querySelector('#version-1-content').innerHTML = renderHighlightedContent(v1.content, changes, false);
    container.querySelector('#version-2-content').innerHTML = renderHighlightedContent(v2.content, changes, true);

    // 変更箇所一覧表示
    container.querySelector('#changes-list').innerHTML = renderChangesList(changes);
  }

  // ===== 6. リセット =====
  function resetComparison() {
    container.querySelector('[data-testid="document-select"]').value = '';
    container.querySelector('[data-testid="document-id-select"]').value = '';
    container.querySelector('[data-testid="version-1-select"]').value = '';
    container.querySelector('[data-testid="version-2-select"]').value = '';
    container.querySelector('#version-1-content').innerHTML = '<p style="margin: 0 0 1rem 0;">契約内容がここに表示されます...</p>';
    container.querySelector('#version-2-content').innerHTML = '<p style="margin: 0 0 1rem 0;">契約内容がここに表示されます...</p>';
    container.querySelector('#changes-list').innerHTML = '<p style="color: var(--text-muted); font-size: 0.875rem;">変更なし</p>';
  }

  // ===== 7. エクスポート =====
  function exportComparison() {
    const docType = container.querySelector('[data-testid="document-select"]').value;
    const docId = container.querySelector('[data-testid="document-id-select"]').value;
    const version1Id = container.querySelector('[data-testid="version-1-select"]').value;
    const version2Id = container.querySelector('[data-testid="version-2-select"]').value;

    if (!docId || !version1Id || !version2Id) {
      alert('比較を実行してからエクスポートしてください');
      return;
    }

    const doc = sampleVersions[docId];
    const v1 = doc.versions.find(v => v.id === version1Id);
    const v2 = doc.versions.find(v => v.id === version2Id);

    const changes = calculateDiff(v1.content, v2.content);
    const changesSummary = changes.map(c => {
      if (c.type === 'added') return `[追加] ${c.line}`;
      if (c.type === 'deleted') return `[削除] ${c.line}`;
      if (c.type === 'modified') return `[変更] ${c.oldLine} → ${c.newLine}`;
    }).join('\n');

    const csv = `\uFEFFドキュメント,${doc.name}\nドキュメントタイプ,${docType}\nバージョン1,v${v1.number}.0 (${v1.date})\nバージョン2,v${v2.number}.0 (${v2.date})\n\n変更箇所:\n${changesSummary}`;

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `comparison_${docId}_${version1Id}_${version2Id}.csv`;
    link.click();
  }

  // ===== 8. イベントリスナー登録 =====
  container.querySelector('[data-testid="compare-button"]').addEventListener('click', executeComparison);
  container.querySelector('[data-testid="reset-button"]').addEventListener('click', resetComparison);
  container.querySelector('[data-testid="export-comparison-button"]').addEventListener('click', exportComparison);

  container.querySelector('[data-testid="back-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781943098977'); // 契約書管理画面へ
  });

  container.querySelector('[data-testid="approve-button"]').addEventListener('click', () => {
    alert('バージョン 2 を承認しました');
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const CONTRACT_VERSION_IDX = 0;  // 契約書バージョン
  const PROPOSAL_VERSION_IDX = 1;  // 提案資料バージョン
  const HISTORY_IDX = 2;            // 変更履歴

  let currentType = 'contract';
  let selectedMaterialId = null;
  let uploadedFile = null;

  // ===== 1. 資料一覧の再描画 =====
  function renderMaterialList(type) {
    const tbody = container.querySelector('#material-tbody');
    const rows = tables[type === 'contract' ? CONTRACT_VERSION_IDX : PROPOSAL_VERSION_IDX].records || [];

    // 同じ type の資料をグループ化して表示（実装簡略化のため、ここではサンプルデータを使用）
    const materials = [
      { id: 'mat-1', name: '基本契約書 v1', type: 'contract' },
      { id: 'mat-2', name: 'NDA契約 v2', type: 'contract' },
      { id: 'mat-3', name: '提案資料 2024Q1', type: 'proposal' }
    ].filter(m => m.type === type);

    tbody.innerHTML = materials.map(m => `
      <tr style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;" 
          class="material-row" data-id="${m.id}" data-type="${m.type}">
        <td style="padding: 8px 10px; color: var(--text);">${m.name}</td>
      </tr>
    `).join('');
  }

  // ===== 2. 変更履歴タイムラインの再描画 =====
  function renderHistoryTimeline(materialId) {
    const timeline = container.querySelector('#history-timeline');
    const historyRows = tables[HISTORY_IDX].records || [];

    // materialId に関連する履歴をフィルタ
    const filtered = historyRows.filter(h => h.対象ID === materialId || h.targetId === materialId);

    if (filtered.length === 0) {
      timeline.innerHTML = '<div style="font-size: 11px; color: var(--text-muted); text-align: center; padding: 20px 10px;">履歴がありません</div>';
      return;
    }

    timeline.innerHTML = filtered.map((h, idx) => `
      <div style="margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.08); position: relative;">
        <div style="display: flex; align-items: flex-start; gap: 8px;">
          <div style="width: 6px; height: 6px; background: var(--primary); border-radius: 50%; margin-top: 5px; flex-shrink: 0;"></div>
          <div style="flex: 1; min-width: 0;">
            <div style="font-size: 11px; font-weight: 500; color: var(--text);">${h.変更種別 || h.changeType || '変更'}</div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${h.変更理由 || h.changeReason || '（理由なし）'}</div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 3px;">
              ${h.作成者ID || h.createdBy || '不明'} · ${h.作成日時 || h.createdAt || '日時不明'}
            </div>
          </div>
        </div>
      </div>
    `).join('');
  }

  // ===== 3. 資料種別切り替え =====
  container.querySelectorAll('.type-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const type = e.target.dataset.type;
      currentType = type;

      // ボタンスタイル更新
      container.querySelectorAll('.type-toggle').forEach(b => {
        if (b.dataset.type === type) {
          b.style.background = 'var(--primary)';
          b.style.color = '#fff';
        } else {
          b.style.background = 'transparent';
          b.style.color = 'var(--text)';
        }
      });

      renderMaterialList(type);
      selectedMaterialId = null;
      container.querySelector('#history-timeline').innerHTML = '<div style="font-size: 11px; color: var(--text-muted); text-align: center; padding: 20px 10px;">資料を選択してください</div>';
    });
  });

  // ===== 4. 資料行クリック =====
  container.addEventListener('click', (e) => {
    const row = e.target.closest('.material-row');
    if (row) {
      selectedMaterialId = row.dataset.id;

      // 行のハイライト
      container.querySelectorAll('.material-row').forEach(r => {
        r.style.background = r === row ? 'rgba(var(--primary-rgb), 0.15)' : 'var(--bg-card)';
      });

      renderHistoryTimeline(selectedMaterialId);
    }
  });

  // ===== 5. ファイルアップロード =====
  const uploadZone = container.querySelector('#upload-zone');
  const fileInput = container.querySelector('#file-input');
  const fileName = container.querySelector('#file-name');

  uploadZone.addEventListener('click', () => fileInput.click());

  uploadZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadZone.style.background = 'rgba(var(--primary-rgb), 0.2)';
    uploadZone.style.borderColor = 'var(--primary)';
  });

  uploadZone.addEventListener('dragleave', () => {
    uploadZone.style.background = 'rgba(0,0,0,0.15)';
    uploadZone.style.borderColor = 'rgba(255,255,255,0.2)';
  });

  uploadZone.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadZone.style.background = 'rgba(0,0,0,0.15)';
    uploadZone.style.borderColor = 'rgba(255,255,255,0.2)';

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      uploadedFile = files[0];
      fileName.textContent = uploadedFile.name;
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      uploadedFile = e.target.files[0];
      fileName.textContent = uploadedFile.name;
    }
  });

  // ===== 6. 保存ボタン =====
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const versionNumber = container.querySelector('[name="versionNumber"]').value;
    const status = container.querySelector('[name="status"]').value;
    const title = container.querySelector('[name="title"]').value;
    const changeDescription = container.querySelector('[name="changeDescription"]').value;
    const tags = container.querySelector('[name="tags"]').value;

    if (!versionNumber || !status || !title) {
      alert('バージョン番号、ステータス、タイトルは必須です');
      return;
    }

    if (!selectedMaterialId) {
      alert('資料を選択してください');
      return;
    }

    const tableIdx = currentType === 'contract' ? CONTRACT_VERSION_IDX : PROPOSAL_VERSION_IDX;
    const payload = {
      バージョン番号: parseInt(versionNumber),
      ステータス: status,
      タイトル: title,
      変更内容: changeDescription,
      タグ: tags,
      ファイルパス: uploadedFile ? uploadedFile.name : '',
      作成者ID: 'user-001',
      作成日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(tableIdx, payload);
    if (saved) {
      alert('バージョン情報を保存しました');
      // フォームリセット
      container.querySelector('[name="versionNumber"]').value = '';
      container.querySelector('[name="status"]').value = '';
      container.querySelector('[name="title"]').value = '';
      container.querySelector('[name="changeDescription"]').value = '';
      container.querySelector('[name="tags"]').value = '';
      fileName.textContent = '';
      uploadedFile = null;

      // 履歴を再描画
      renderHistoryTimeline(selectedMaterialId);
    }
  });

  // ===== 7. キャンセルボタン =====
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('[name="versionNumber"]').value = '';
    container.querySelector('[name="status"]').value = '';
    container.querySelector('[name="title"]').value = '';
    container.querySelector('[name="changeDescription"]').value = '';
    container.querySelector('[name="tags"]').value = '';
    container.querySelector('#file-name').textContent = '';
    uploadedFile = null;
  });

  // ===== 8. 初期化 =====
  renderMaterialList('contract');
}

function(container, apiUrl, tables) {
  // ===== 1. 状態管理 =====
  let currentDocType = 'contract';
  let selectedDocument = null;
  let versionData = [];
  let currentLatestVersion = null;
  let selectedLatestVersion = null;
  let selectedArchiveVersions = new Set();

  // ===== 2. ヘルパー関数 =====
  function showMessage(text, type = 'success') {
    const msgContainer = container.querySelector('#message-container');
    const msg = document.createElement('div');
    msg.style.cssText = `
      padding: 0.75rem 1rem;
      border-radius: 0.25rem;
      font-size: 0.875rem;
      background: ${type === 'success' ? 'rgba(34, 197, 94, 0.15)' : 'rgba(239, 68, 68, 0.15)'};
      color: ${type === 'success' ? '#22c55e' : '#ef4444'};
      border-left: 3px solid ${type === 'success' ? '#22c55e' : '#ef4444'};
    `;
    msg.textContent = text;
    msgContainer.appendChild(msg);
    setTimeout(() => msg.remove(), 3000);
  }

  function renderVersionList() {
    const tbody = container.querySelector('#version-tbody');
    if (!versionData || versionData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted);">バージョンデータなし</td></tr>';
      return;
    }

    tbody.innerHTML = versionData.map(v => {
      const isLatest = currentLatestVersion && currentLatestVersion.id === v.id;
      return `
        <tr data-version-id="${v.id}" style="background: ${isLatest ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}; border-bottom: 1px solid rgba(255,255,255,0.08);">
          <td style="padding: 0.5rem; color: var(--text); font-weight: ${isLatest ? '600' : '400'};">${v.versionNumber || 'N/A'}</td>
          <td style="padding: 0.5rem; color: var(--text-muted); font-size: 0.75rem;">${v.status || 'N/A'}</td>
          <td style="padding: 0.5rem; color: var(--text-muted); font-size: 0.75rem;">${v.createdAt ? new Date(v.createdAt).toLocaleDateString('ja-JP') : 'N/A'}</td>
          <td style="padding: 0.5rem; text-align: center;">
            ${isLatest ? '<span style="color: var(--primary); font-weight: 600; font-size: 0.75rem;">●</span>' : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  function renderLatestRadioGroup() {
    const group = container.querySelector('#latest-radio-group');
    if (!versionData || versionData.length === 0) {
      group.innerHTML = '';
      return;
    }

    group.innerHTML = versionData.map(v => `
      <div style="display: flex; align-items: center; gap: 0.5rem;">
        <input type="radio" name="new-latest" value="${v.id}" id="radio-${v.id}" data-testid="radio-latest-${v.id}" style="accent-color: var(--primary);" />
        <label for="radio-${v.id}" style="font-size: 0.8rem; color: var(--text); cursor: pointer;">Ver ${v.versionNumber} (${v.status})</label>
      </div>
    `).join('');
  }

  function renderArchiveCheckboxGroup() {
    const group = container.querySelector('#archive-checkbox-group');
    if (!versionData || versionData.length === 0) {
      group.innerHTML = '';
      return;
    }

    group.innerHTML = versionData.map(v => {
      const isLatest = currentLatestVersion && currentLatestVersion.id === v.id;
      return `
        <div style="display: flex; align-items: center; gap: 0.5rem; opacity: ${isLatest ? '0.5' : '1'}; pointer-events: ${isLatest ? 'none' : 'auto'};">
          <input type="checkbox" class="archive-checkbox" value="${v.id}" id="archive-${v.id}" data-testid="archive-${v.id}" style="accent-color: var(--primary);" ${isLatest ? 'disabled' : ''} />
          <label for="archive-${v.id}" style="font-size: 0.8rem; color: var(--text); cursor: pointer;">Ver ${v.versionNumber} ${isLatest ? '(最新版)' : ''}</label>
        </div>
