  container.querySelector('#btn-archive').addEventListener('click', async () => {
    if (!selectedDocument) {
      showMessage('対象文書を選択してください', 'error');
      return;
    }
    if (selectedArchiveVersions.size === 0) {
      showMessage('アーカイブ対象を選択してください', 'error');
      return;
    }

    const reason = container.querySelector('#archive-reason').value.trim();
    if (!reason) {
      showMessage('アーカイブ理由を入力してください', 'error');
      return;
