    // API呼び出し（実装例）
    try {
      // const result = await window.aivicApi.update(tableIndex, selectedDocument, { archivedVersionIds: Array.from(selectedArchiveVersions), archiveReason: reason });
      versionData = versionData.filter(v => !selectedArchiveVersions.has(v.id));
