function(container, apiUrl, tables) {
  // テーブルインデックスの決定（契約書と提案資料の統合表示）
  // tables[0] = 契約書, tables[1] = 提案資料, tables[2] = 変更履歴
  const contractTableIndex = 0;
  const proposalTableIndex = 1;
  const historyTableIndex = 2;

  // DOM 要素の取得
  const inputKeyword = container.querySelector("#input-keyword");
  const filterType = container.querySelector("#filter-type");
  const filterStatus = container.querySelector("#filter-status");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExport = container.querySelector("#btn-export");
  const resultTbody = container.querySelector("#result-tbody");
  const resultCount = container.querySelector("#result-count");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const detailPlaceholder = container.querySelector("#detail-panel > div:first-child");

  // 統合データ（契約書 + 提案資料）
  let allRecords = [];
  let filteredRecords = [];

  // ステータスバッジの色付け
  function getStatusBadgeStyle(status) {
    const styles = {
      "草案": "background: rgba(100,116,139,0.3); color: #cbd5e1;",
      "承認待ち": "background: rgba(251,146,60,0.3); color: #fed7aa;",
      "有効": "background: rgba(34,197,94,0.3); color: #bbf7d0;",
      "終了": "background: rgba(107,114,128,0.3); color: #d1d5db;",
      "キャンセル": "background: rgba(239,68,68,0.3); color: #fca5a5;",
      "下書き": "background: rgba(100,116,139,0.3); color: #cbd5e1;",
      "提案中": "background: rgba(59,130,246,0.3); color: #bfdbfe;",
      "契約済み": "background: rgba(34,197,94,0.3); color: #bbf7d0;",
      "却下": "background: rgba(239,68,68,0.3); color: #fca5a5;"
    };
    return styles[status] || "background: rgba(100,116,139,0.3); color: #cbd5e1;";
  }

  function getTypeBadgeStyle(type) {
    if (type === "契約書") {
      return "background: rgba(59,130,246,0.3); color: #bfdbfe;";
    } else if (type === "提案資料") {
      return "background: rgba(168,85,247,0.3); color: #e9d5ff;";
    }
    return "background: rgba(100,116,139,0.3); color: #cbd5e1;";
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return "-";
    const d = new Date(dateStr);
    return d.toLocaleDateString("ja-JP", { year: "numeric", month: "2-digit", day: "2-digit" });
  }

  // 再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      resultTbody.innerHTML = '<tr style="height: 2rem;"><td colspan="5" style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.875rem;">検索結果がありません</td></tr>';
      resultCount.textContent = "0";
      return;
    }

    resultTbody.innerHTML = rows.map(r => {
      const name = r.契約書名 || r.提案資料名 || "-";
      const type = r.契約種別 ? "契約書" : "提案資料";
      const status = r.ステータス || "-";
      const created = formatDate(r.作成日時);
      const updated = formatDate(r.更新日時);
      return `
        <tr data-id="${r.id}" data-type="${type}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 0.75rem; color: var(--text);">${name}</td>
          <td style="padding: 0.75rem; color: var(--text);">${type}</td>
          <td style="padding: 0.75rem;"><span style="${getStatusBadgeStyle(status)}">${status}</span></td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.8rem;">${created}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.8rem;">${updated}</td>
        </tr>
      `;
    }).join("");
    resultCount.textContent = rows.length;
  }

  // 詳細パネルの表示
  async function showDetail(recordId, recordType) {
    const tableIndex = recordType === "契約書" ? contractTableIndex : proposalTableIndex;
    const allData = await window.aivicApi.list(tableIndex);
    const record = allData.find(r => r.id === recordId);

    if (!record) return;

    // 基本情報の表示
    const name = record.契約書名 || record.提案資料名 || "-";
    container.querySelector("#detail-name").textContent = name;

    const typeBadge = container.querySelector("#detail-type-badge");
    typeBadge.textContent = recordType;
    typeBadge.style.cssText = getTypeBadgeStyle(recordType);

    const statusBadge = container.querySelector("#detail-status-badge");
    statusBadge.textContent = record.ステータス || "-";
    statusBadge.style.cssText = getStatusBadgeStyle(record.ステータス);

    container.querySelector("#detail-created").textContent = formatDate(record.作成日時);
    container.querySelector("#detail-updated").textContent = formatDate(record.更新日時);

    // 担当者情報の取得と表示
    const ownerDiv = container.querySelector("#detail-owner");
    if (record.担当者ID || record.ユーザーID) {
      const userId = record.担当者ID || record.ユーザーID;
      const users = await window.aivicApi.list(3); // ユーザーテーブル
      const user = users.find(u => u.id === userId);
      ownerDiv.textContent = user ? user.氏名 : "-";
    } else {
      ownerDiv.textContent = "-";
    }

    // 変更履歴の取得と表示
    const historyDiv = container.querySelector("#detail-history");
    const allHistory = await window.aivicApi.list(historyTableIndex);
    const recordHistory = allHistory.filter(h => h.対象ID === recordId);

    if (recordHistory.length === 0) {
      historyDiv.innerHTML = '<div style="color: var(--text-muted); font-size: 0.8rem;">変更履歴はありません</div>';
    } else {
      historyDiv.innerHTML = recordHistory
        .sort((a, b) => new Date(b.作成日時) - new Date(a.作成日時))
        .slice(0, 10)
        .map(h => `
          <div style="padding: 0.5rem; background: rgba(0,0,0,0.2); border-radius: 0.25rem; border-left: 2px solid var(--primary);">
            <div style="color: var(--text); font-weight: 500;">${h.変更種別}</div>
            <div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.25rem;">${formatDate(h.作成日時)}</div>
            ${h.変更フィールド ? `<div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.25rem;">${h.変更フィールド}: ${h.変更前値} → ${h.変更後値}</div>` : ""}
          </div>
        `).join("");
    }

    // パネルの表示
    detailPlaceholder.style.display = "none";
    detailContent.style.display = "flex";
  }

  // 検索実行
  async function executeSearch() {
    const keyword = inputKeyword.value.toLowerCase();
    const type = filterType.value;
    const status = filterStatus.value;
    const dateFrom = filterDateFrom.value;

    // 契約書と提案資料を取得
    const contracts = await window.aivicApi.list(contractTableIndex) || [];
    const proposals = await window.aivicApi.list(proposalTableIndex) || [];

    // 統合データの作成
    allRecords = [
      ...contracts.map(c => ({ ...c, _type: "契約書" })),
      ...proposals.map(p => ({ ...p, _type: "提案資料" }))
    ];

    // フィルタリング
    filteredRecords = allRecords.filter(r => {
      const name = (r.契約書名 || r.提案資料名 || "").toLowerCase();
      const desc = (r.契約書説明 || r.説明 || "").toLowerCase();
      const matchKeyword = !keyword || name.includes(keyword) || desc.includes(keyword);
      const matchType = !type || r._type === type;
      const matchStatus = !status || r.ステータス === status;
      const matchDate = !dateFrom || new Date(r.作成日時) >= new Date(dateFrom);
      return matchKeyword && matchType && matchStatus && matchDate;
    });

    renderRows(filteredRecords);
  }

  // リセット
  function resetFilters() {
    inputKeyword.value = "";
    filterType.value = "";
    filterStatus.value = "";
    filterDateFrom.value = "";
    resultTbody.innerHTML = '<tr style="height: 2rem;"><td colspan="5" style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.875rem;">検索条件を入力して「検索」をクリックしてください</td></tr>';
    resultCount.textContent = "0";
    detailPlaceholder.style.display = "block";
    detailContent.style.display = "none";
  }

  // CSV エクスポート
  function exportCSV() {
    if (filteredRecords.length === 0) {
      alert("エクスポート対象のデータがありません");
      return;
    }

    const headers = ["資料名", "種別", "ステータス", "作成日", "最終更新日"];
    const rows = filteredRecords.map(r => [
      r.契約書名 || r.提案資料名 || "",
      r._type,
      r.ステータス || "",
      formatDate(r.作成日時),
      formatDate(r.更新日時)
    ]);

    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv; charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `資料検索結果_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  }

  // イベントリスナー登録
  btnSearch.addEventListener("click", executeSearch);
  btnReset.addEventListener("click", resetFilters);
  btnExport.addEventListener("click", exportCSV);

  // 行クリックで詳細表示
  container.addEventListener("click", e => {
    const tr = e.target.closest("tr[data-id]");
    if (tr) {
      const recordId = tr.dataset.id;
      const recordType = tr.dataset.type;
      showDetail(recordId, recordType);
    }
  });

  // 初期データの表示（初期状態では検索結果なし）
  renderRows([]);
}

