      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">更新日</div>
        <div style="font-size: 12px; color: var(--text);">${updatedDate}</div>
      </div>
    `;

    // バージョン情報を表示（ダミー）
    versionList.innerHTML = `
      <div style="padding: 6px; background: rgba(255,255,255,0.04); border-radius: 3px; font-size: 11px; color: var(--text-muted);">
        <div style="font-weight: 500; color: var(--text); margin-bottom: 2px;">v1.0 (現在)</div>
        <div>${createdDate}</div>
      </div>
    `;

    panelDetail.style.display = "flex";
  }

  // 初期データ描画
  renderRows(tables[0]?.records || []);
  allRecords = tables[0]?.records || [];

  // 作成者フィルタを動的に生成
  const creatorSelect = container.querySelector("#select-creator");
  const creators = [...new Set((tables[0]?.records || []).map(r => r.creator_name || r.created_by || "不明"))];
  creators.forEach(creator => {
    const opt = document.createElement("option");
    opt.value = creator;
    opt.textContent = creator;
    creatorSelect.appendChild(opt);
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const type = container.querySelector("#select-type").value;
    const status = container.querySelector("#select-status").value;
    const creator = container.querySelector("#select-creator").value;
    const createdFrom = container.querySelector("#input-created-from").value;
    const createdTo = container.querySelector("#input-created-to").value;
    const updatedFrom = container.querySelector("#input-updated-from").value;
    const updatedTo = container.querySelector("#input-updated-to").value;

    const filtered = allRecords.filter(r => {
      const name = (r.contract_name || r.proposal_name || r.name || "").toLowerCase();
      const desc = (r.description || r.contract_description || "").toLowerCase();
      const rType = r.contract_name ? "contract" : "proposal";
      const rStatus = r.status || "draft";
      const rCreator = r.creator_name || r.created_by || "不明";
      const rCreated = r.created_at ? new Date(r.created_at).toISOString().split("T")[0] : "";
      const rUpdated = r.updated_at ? new Date(r.updated_at).toISOString().split("T")[0] : "";

      const keywordMatch = !keyword || name.includes(keyword) || desc.includes(keyword);
      const typeMatch = !type || rType === type;
      const statusMatch = !status || rStatus === status;
      const creatorMatch = !creator || rCreator === creator;
      const createdFromMatch = !createdFrom || rCreated >= createdFrom;
      const createdToMatch = !createdTo || rCreated <= createdTo;
      const updatedFromMatch = !updatedFrom || rUpdated >= updatedFrom;
      const updatedToMatch = !updatedTo || rUpdated <= updatedTo;

      return keywordMatch && typeMatch && statusMatch && creatorMatch && createdFromMatch && createdToMatch && updatedFromMatch && updatedToMatch;
    });

    renderRows(filtered);
    panelDetail.style.display = "none";
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-keyword").value = "";
    container.querySelector("#select-type").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#select-creator").value = "";
    container.querySelector("#input-created-from").value = "";
    container.querySelector("#input-created-to").value = "";
    container.querySelector("#input-updated-from").value = "";
    container.querySelector("#input-updated-to").value = "";
    renderRows(allRecords);
    panelDetail.style.display = "none";
  });

  // CSV出力ボタン
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = Array.from(tbody.querySelectorAll("tr")).slice(0, -1);
    if (rows.length === 0) {
      alert("出力するデータがありません");
      return;
    }
    const headers = ["資料名", "種別", "ステータス", "作成者", "作成日"];
    const csv = [headers.join(",")];
    rows.forEach(row => {
      const cells = row.querySelectorAll("td");
      const name = cells[0]?.textContent || "";
      const type = cells[1]?.textContent || "";
      const status = cells[2]?.textContent || "";
      const creator = cells[3]?.textContent || "";
      const date = cells[4]?.textContent || "";
      csv.push([name, type, status, creator, date].map(v => `"${v.replace(/"/g, '""')}"`).join(","));
    });
    const blob = new Blob(["\uFEFF" + csv.join("\n")], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "search_results.csv";
    link.click();
  });

  // 詳細パネルを閉じる
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    panelDetail.style.display = "none";
  });

  // 行クリックで詳細表示
  container.addEventListener("click", e => {
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const record = allRecords.find(r => r.id === id);
      if (record) showDetail(record);
    }
  });

  // バージョン比較ボタン
  container.querySelector("#btn-compare-version").addEventListener("click", () => {
    if (selectedRecord) {
      window.showScreen("scr-1781943125510");
    }
  });

  // 変更履歴ボタン
  container.querySelector("#btn-view-history").addEventListener("click", () => {
    if (selectedRecord) {
      window.showScreen("scr-1781943180410");
    }
  });
}
